import { editAccountPassword } from '~/client';
import type { EditPasswordRequest, EditPasswordResponse } from '~/client';

export const useEditUserPassword = defineMutation(() => {
  const {
    mutateAsync: editUserPassword,
    asyncStatus,
    error,
    status,
  } = useMutation({
    mutation: (editPasswordForm: EditPasswordRequest): Promise<EditPasswordResponse> =>
      editAccountPassword({
        composable: '$fetch',
        body: editPasswordForm,
      }),
    onSuccess: async () => {
      await navigateTo({ name: 'account' });
      showToastSuccess('Password updated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    status,
    error,
    editUserPassword,
    isEditingUserPassword: computed(() => asyncStatus.value === 'loading'),
  };
});
