<template>
  <section class="flex flex-col gap-10">
    <h1 class="font-semibold text-3xl">My Account</h1>

    <section class="flex flex-col w-full gap-4">
      <GoBackButton subject="account" :fallback-to="{ name: 'account' }" />
      <Card class="w-full flex flex-col max-w-[700px] justify-center self-center">
        <CardHeader>
          <CardTitle class="p-0 text-lg font-semibold">Edit Password</CardTitle>
        </CardHeader>
        <CardContent>
          <form
            id="edit-password-form"
            class="self-center flex flex-col gap-6 flex-auto w-full justify-center max-w-[700px] max-lg:px-0"
            @submit="onSubmit"
          >
            <FormItemWrapper v-for="input in passwordInputs" :key="input.name" :label="input.label" :name="input.name">
              <template #default="{ slots }">
                <KitFormPasswordInput
                  :id="input.name"
                  :placeholder="input.placeholder"
                  :component-field="slots.componentField"
                  :disabled="isEditingUserPassword"
                  :autocomplete="input.name"
                />
              </template>
            </FormItemWrapper>
            <Button type="submit" form="edit-password-form" :loading="isEditingUserPassword">Save New Password</Button>
          </form>
        </CardContent>
      </Card>
    </section>
  </section>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { useEditUserPassword } from '~/mutations/account';
import { passwordInputs } from '~/constants/account';
import { passwordRegex } from '~/constants/regularExpressions';

const formSchema = toTypedSchema(
  z
    .object({
      old_password: z
        .string({ message: 'Old password is required' })
        .trim()
        .nonempty({ message: 'Old password is required' }),
      new_password: z.string({ message: 'New password is required' }).regex(passwordRegex, {
        message:
          'New password must contain at least 8 characters, with upper and lowercase letters, a number, a special symbol, and no spaces',
      }),
      confirm_new_password: z
        .string({ message: 'Confirmation password is required' })
        .trim()
        .nonempty({ message: 'Confirmation password is required' }),
    })
    .refine((data) => data.confirm_new_password === data.new_password, {
      message: 'Confirmation password must match the new password',
      path: ['confirm_new_password'],
    })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const { editUserPassword, isEditingUserPassword } = useEditUserPassword();

const onSubmit = handleSubmit(async (values) => {
  console.log('Form submitted with values:', values);
  const requestValues = {
    old_password: values.old_password,
    new_password: values.new_password,
  };
  await editUserPassword(requestValues).catch((error) => {
    console.error('Error submitting form:', error);
  });
});
</script>

<style scoped lang="scss"></style>
